import { useState } from 'react';
import {
  JxToggle,
  JxSlider,
  JxSwitch,
  JxDivider,
  JxSelect,
  JxBadge,
} from '@jinx-ui/react';

type Theme = 'light' | 'dark' | 'system';

export interface AppearanceSettingsValue {
  theme: Theme;
  scale: number;
  dense: boolean;
  font: string;
}

interface AppearanceSettingsProps {
  onChange?: (value: AppearanceSettingsValue) => void;
}

const themeLabels: Record<Theme, string> = {
  light: 'Светлая',
  dark: 'Тёмная',
  system: 'Системная',
};

export default function AppearanceSettings({ onChange }: AppearanceSettingsProps) {
  const [theme, setTheme] = useState<Theme>('system');
  const [scale, setScale] = useState(100);
  const [dense, setDense] = useState(false);
  const [font, setFont] = useState('system');

  const emit = (next: Partial<AppearanceSettingsValue>) => {
    const merged: AppearanceSettingsValue = { theme, scale, dense, font, ...next };
    onChange?.(merged);
  };

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-space-lg, 24px)' }}>
      <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
        <h2 style={{ margin: 0, color: 'var(--jx-color-text)' }}>Внешний вид</h2>
        <JxBadge tone="accent">{themeLabels[theme]}</JxBadge>
      </div>

      <JxToggle
        items={[
          { value: 'light', label: 'Светлая' },
          { value: 'dark', label: 'Тёмная' },
          { value: 'system', label: 'Системная' },
        ]}
        value={theme}
        onValueChange={(value) => {
          const next = value as Theme;
          setTheme(next);
          emit({ theme: next });
        }}
      />

      <JxSlider
        label="Масштаб интерфейса"
        min={80}
        max={140}
        step={5}
        unit="%"
        showOutput
        value={scale}
        onValueChange={(value) => {
          setScale(value);
          emit({ scale: value });
        }}
      />

      <JxSwitch
        label="Плотная вёрстка"
        checked={dense}
        onChange={(event) => {
          const next = event.target.checked;
          setDense(next);
          emit({ dense: next });
        }}
      />

      <JxDivider label="Ещё" />

      <JxSelect
        label="Шрифт"
        options={[
          { value: 'system', label: 'Системный' },
          { value: 'inter', label: 'Inter' },
          { value: 'roboto', label: 'Roboto' },
          { value: 'mono', label: 'Моноширинный' },
        ]}
        value={font}
        onValueChange={(value) => {
          setFont(value);
          emit({ font: value });
        }}
      />
    </div>
  );
}

